```go
package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"os"

	"github.com/confluentinc/confluent-kafka-go/kafka"
)

// Struct represents the structure of a Go source file.
type Struct struct {
	Name        string     // The name of the struct being defined.
	PackageName string     // The package where the struct is defined.
	Fields      []Field    // A list of field definitions.
}

// Field represents the fields of a Go struct.
type Field struct {
	Type   string // The type of the field.
	Name   string // The name of the field.
	Options []string // Additional options (not used here).
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run parser.go <source_file> <struct_name>")
		return
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	parsedFile, err := parser.ParseFile(token.NewFileSet(), sourceFile, nil, parser.ParseComments)
	if err != nil {
		fmt.Printf("Failed to parse the file: %v\n", err)
		return
	}

	// Extracting the struct definition
	structDef := extractStructDefinition(parsedFile, structName)

	// Writing the Avro schema to a file
	schemaBytes, err := json.Marshal(structDef)
	if err != nil {
		fmt.Printf("Failed to marshal the struct def: %v\n", err)
		return
	}
	outputPath := fmt.Sprintf("%s.avsc", structName)
	err = ioutil.WriteFile(outputPath, schemaBytes, 0644)
	if err != nil {
		fmt.Printf("Failed to write the schema to file: %v\n", err)
		return
	}
	fmt.Printf("Generated AVRO schema for %s.avsc successfully.\n", structName)
}

// extractStructDefinition extracts the struct definition from the parsed AST.
func extractStructDefinition(node ast.Node, structName string) *Struct {
	switch n := node.(type) {
	case *ast.GenDecl:
		for _, spec := range n.Specs {
			if f, ok := spec.(*ast.StructType); ok && f.Name.Name == structName {
				return &Struct{
					Name:        structName,
					PackageName: f.Type.Package.Name,
					Fields:      getFields(f),
				}
			}
		}
	}

	return nil
}

// getFields returns all the fields of the specified struct.
func getFields(spec *ast.StructType) []*Field {
	var fields []*Field
	for i := 0; i < len(spec.Fields.List); i++ {
		field := spec.Fields.List[i].(*ast.Field)
		fields = append(fields, &Field{
			Type:   field.Type.String(),
			Name:   field.Name.Name,
			Options: field.Type.Options,
		})
	}
	return fields
}
```

